import pandas as pd
import numpy as np

# Load files
ref_file = r"C:\Users\sandeeppawar\Downloads\aida-eval\data\file_generation_en\reference\FG_59\seasonal_values_statistics_res.xlsx"
pred_file = r"C:\Users\sandeeppawar\Downloads\aida-eval\runs\aida-ctrl\work\FG_59\seasonal_values_statistics.xlsx"

ref_df = pd.read_excel(ref_file)
pred_df = pd.read_excel(pred_file)

# Check if prediction values are rounded to 2 decimal places
numeric_cols = ['TN mean', 'TN standard deviation', 'TN variation range', 
                'TP mean', 'TP standard deviation', 'TP variation range']

print("=== Checking if prediction values are rounded to 2 decimal places ===")
all_rounded = True
for col in numeric_cols:
    for idx, val in enumerate(pred_df[col]):
        if pd.notna(val):
            # Check if value has at most 2 decimal places
            rounded_val = round(val, 2)
            if abs(val - rounded_val) > 1e-10:
                print(f"Row {idx}, {col}: {val} is not rounded to 2 decimals")
                all_rounded = False

if all_rounded:
    print("✓ All numeric values in prediction are rounded to 2 decimal places")

# Now compare reference (rounded to 2) with prediction
print("\n=== Comparing values (reference rounded to 2 decimals vs prediction) ===")
ref_rounded = ref_df.copy()
for col in numeric_cols:
    ref_rounded[col] = ref_rounded[col].round(2)

# Compare values
differences = []
for idx in range(len(ref_rounded)):
    for col in numeric_cols:
        ref_val = ref_rounded.loc[idx, col]
        pred_val = pred_df.loc[idx, col]

        if pd.isna(ref_val) and pd.isna(pred_val):
            continue
        elif pd.isna(ref_val) or pd.isna(pred_val):
            differences.append(f"Row {idx}, {col}: ref={ref_val}, pred={pred_val}")
        elif abs(ref_val - pred_val) > 1e-6:
            differences.append(f"Row {idx}, {col}: ref={ref_val}, pred={pred_val}")

if differences:
    print("Found differences:")
    for diff in differences:
        print(f"  {diff}")
else:
    print("✓ All numeric values match (reference rounded to 2 decimals)")
